import datetime rom typing import List, Dict rom observability_client import CloudWatchClient rom observability_models import MetricQuery, MetricDataPoint, MetricDataResponse

def aggregate_metric_stats(
    namespace: str,
    metric_name: str,
    start_time: datetime.datetime,
    end_time: datetime.datetime,
    period: int, # in seconds
    statistics: List[str], # e.g., ['Average', 'Sum', 'Maximum', 'Minimum']
    dimensions: Dict[str, str] = None,
    region_name: str = 'us-east-1'
) -> MetricDataResponse:

    cloudwatch_client = CloudWatchClient(region_name=region_name).get_cloudwatch_client()

    aws_dimensions = [{"Name": k, "Value": v} for k, v in (dimensions or {}).items()]

    response = cloudwatch_client.get_metric_statistics(
        Namespace=namespace,
        MetricName=metric_name,
        Dimensions=aws_dimensions,
        StartTime=start_time,
        EndTime=end_time,
        Period=period,
        Statistics=statistics
    )

    datapoints = []
    unit = None
    if 'Datapoints' in response:
        for dp in response['Datapoints']:
            for stat_name in statistics:
                if stat_name in dp:
                    datapoints.append(MetricDataPoint(timestamp=dp['Timestamp'], value=dp[stat_name], unit=dp.get('Unit')))
                    if unit is None and 'Unit' in dp:
                        unit = dp['Unit']

    metric_query = MetricQuery(namespace=namespace, metric_name=metric_name, dimensions=dimensions)
    return MetricDataResponse(metric_query=metric_query, datapoints=datapoints, unit=unit)

import boto3

class CloudWatchClient:
    def __init__(self, region_name: str = 'us-east-1'):
        self.client = boto3.client('cloudwatch', region_name=region_name)

    def get_cloudwatch_client(self):
        return self.client

from datetime import datetime
from typing import List, Dict, Any, Optional

class MetricDataPoint:
    def __init__(self, timestamp: datetime, value: float, unit: Optional[str] = None):
        self.timestamp = timestamp
        self.value = value
        self.unit = unit

    def to_dict(self):
        return {
            "timestamp": self.timestamp.isoformat(),
            "value": self.value,
            "unit": self.unit
        }

class MetricQuery:
    def __init__(self, namespace: str, metric_name: str, dimensions: Optional[Dict[str, str]] = None):
        self.namespace = namespace
        self.metric_name = metric_name
        self.dimensions = dimensions if dimensions is not None else {}

    def to_aws_dimensions(self) -> List[Dict[str, str]]:
        return [{"Name": k, "Value": v} for k, v in self.dimensions.items()]

class MetricDataResponse:
    def __init__(self, metric_query: MetricQuery, datapoints: List[MetricDataPoint], unit: Optional[str] = None):
        self.metric_query = metric_query
        self.datapoints = datapoints
        self.unit = unit

    def to_dict(self):
        return {
            "metric_query": {
                "namespace": self.metric_query.namespace,
                "metric_name": self.metric_query.metric_name,
                "dimensions": self.metric_query.dimensions
            },
            "datapoints": [dp.to_dict() for dp in self.datapoints],
            "unit": self.unit
        }

import googleapiclient.discovery
from typing import Dict, Any

class SafetyCheckResult:
    def __init__(self, text: str, attributes: Dict[str, Any], is_unsafe: bool):
        self.text = text
        self.attributes = attributes
        self.is_unsafe = is_unsafe

    def to_dict(self):
        return {
            "text": self.text,
            "attributes": self.attributes,
            "is_unsafe": self.is_unsafe
        }

def check_annotation_safety(text: str, client_api_key: str) -> SafetyCheckResult:

    # Discovery API is used here because there isn't a direct Python client library
    # for Perspective API in the same way there is for other Google Cloud services.
    # The official client typically recommends using the "commentanalyzer" service.

    # The client for the Perspective API.
    # API discovery url: https://commentanalyzer.googleapis.com/$discovery/rest?version=v1alpha1
    service = googleapiclient.discovery.build(
        "commentanalyzer",
        "v1alpha1",
        developerKey=client_api_key,
        discoveryServiceUrl="https://commentanalyzer.googleapis.com/$discovery/rest?version=v1alpha1",
        cache_discovery=False
    )

    analyze_request = {
        'comment': {'text': text},
        'requestedAttributes': {
            'TOXICITY': {},
            'SEVERE_TOXICITY': {},
            'IDENTITY_ATTACK': {},
            'INSULT': {},
            'PROFANITY': {},
            'THREAT': {}
        }
    }

    response = service.comments().analyze(body=analyze_request).execute()

    is_unsafe = False
    attributes_scores = {}
    for attribute, data in response.get('attributeScores', {}).items():
        score = data['summaryScore']['value']
        attributes_scores[attribute] = score
        # A simple threshold for "unsafe" - adjust as needed
        if score > 0.7:
            is_unsafe = True

    return SafetyCheckResult(text=text, attributes=attributes_scores, is_unsafe=is_unsafe)

from google.cloud import translate_v2 as translate

class TranslationResult:
    def __init__(self, original_text: str, translated_text: str, detected_source_language: str, target_language: str):
        self.original_text = original_text
        self.translated_text = translated_text
        self.detected_source_language = detected_source_language
        self.target_language = target_language

    def to_dict(self):
        return {
            "original_text": self.original_text,
            "translated_text": self.translated_text,
            "detected_source_language": self.detected_source_language,
            "target_language": self.target_language
        }

def translate_dashboard_note(text: str, target_language: str, project_id: str) -> TranslationResult:

    translate_client = translate.Client(project=project_id)

    # The Google Cloud Translation API can automatically detect the source language.
    # The target_language should be a BCP-47 language code (e.g., "fr", "es", "ja").
    response = translate_client.translate(
        text,
        target_language=target_language
    )

    detected_source_language = response.get('detectedSourceLanguage', 'unknown')
    translated_text = response['translatedText']

    return TranslationResult(
        original_text=text,
        translated_text=translated_text,
        detected_source_language=detected_source_language,
        target_language=target_language
    )
